docs = {1: "the cache keeps the hot keys in the cache",
        2: "the deploy broke the cache",
        3: "roll back the deploy"}
pairs = []
for doc_id, text in docs.items():
    for token in text.lower().split():
        pairs.append((token, doc_id))
pairs.sort()
index = {}
for term, doc_id in pairs:
    postings = index.setdefault(term, {})
    postings[doc_id] = postings.get(doc_id, 0) + 1
df = {t: len(p) for t, p in index.items()}
print(index["cache"], df["cache"], df["the"])
